sys_script_include.script:
var RpBmsUtils = Class.create();
RpBmsUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

//TRAZ LABEL DOS CAMPOS DA TABLE PRO RP
    getBaseTableInfo: function() {
        var baseTableId = this.getParameter("sysparm_base_table_id");
        var details = {};

        var grBase = new GlideRecord("x_1092529_bms_ba_0_bases");

        if (grBase.get(baseTableId)) {
            details.city = grBase.getDisplayValue("city");
            details.state = grBase.getDisplayValue("state");
            details.manager = grBase.getDisplayValue("base_manager");
            details.vacancies = grBase.getValue("avaible_vacancies")||0;
        }

        return new global.JSON().encode(details);
    },

// FIM 1

    type: 'RpBmsUtils'
});
